var catalogTools = []catalogTool{
	{"registry", "", "{\"name\":\"whoami\",\"description\":\"Your own stam registry entry: id, name, role, state, the path to your conversation history file, and now (the daemon's clock, ISO UTC).\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"}}}}"},
	{"registry", "", "{\"name\":\"register\",\"description\":\"Join the stam registry, for an agent that stam did not spawn. Gives you an id so others can find and mail you.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"name\":{\"type\":\"string\",\"description\":\"Unique lowercase name with dashes, for example \\\"docs-writer\\\".\"},\"role\":{\"type\":\"string\",\"description\":\"One or two sentences on what you work on.\"},\"harness\":{\"type\":\"string\",\"description\":\"Your harness, for example \\\"claude\\\", \\\"codex\\\", or \\\"opencode\\\".\"},\"model\":{\"type\":\"string\"}},\"required\":[\"name\",\"role\"]}}"},
	{"agents", "", "{\"name\":\"workspace_share\",\"description\":\"Share your personal workspace folder with another agent on this machine. access: 'read' or 'write', or 'none' to stop sharing. The grantee gets a notice now. A revoke ('none') ends a Claude Code grant, or a Codex 'write' grant, at the grantee's next launch; other grants were never sandbox-enforced, so the grantee must stop using the folder. The grantee sees the folder in its \\\"Your workspace\\\" prompt block, and a Claude Code agent gets it as an allowed directory at its next launch (a Codex agent gets 'write' as a writable root). 'read' is advisory: every agent runs as the same Unix user, so stam can't stop a write. You need a personal workspace (spawned with `workspace`). Archiving you keeps the shares; archiving the grantee drops them.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"agent\":{\"type\":\"string\",\"description\":\"The agent to share with: id or name.\"},\"access\":{\"type\":\"string\",\"enum\":[\"read\",\"write\",\"none\"]}},\"required\":[\"agent\",\"access\"]}}"},
	{"registry", "", "{\"name\":\"find_agents\",\"description\":\"Search the stam registry by id, name, or role text. Without a query, lists the live agents you may see (active, paused and shut-down ones; archived ones are left out). With a query, archived agents are left out too, unless the query is exactly an agent's id or name. `state` overrides this: \\\"archived\\\" lists only archived agents, \\\"all\\\" lists every match. `role` keeps only agents whose role or name contains the text (case-insensitive); standing specialists come first, marked standing with their workspace name. Each agent carries its type: the saved type it was spawned as, or null.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"query\":{\"type\":\"string\"},\"role\":{\"type\":\"string\",\"description\":\"Specialty to find, matched against role and name as a case-insensitive substring.\"},\"state\":{\"type\":\"string\",\"enum\":[\"active\",\"archived\",\"all\"],\"description\":\"Which agents to list: active (not archived), archived, or all. Without it: live agents, plus an archived one only on an exact id or name match of the query.\"}}}}"},
	{"registry", "", "{\"name\":\"registry_info\",\"description\":\"Agent types (saved roles such as developer, reviewer, and manager, with when to use each; spawn one with spawn_agent type), harnesses, known models with their inputs (text, image, video), presets with when to use each, and the rule for missing capabilities.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{}}}"},
	{"registry", "", "{\"name\":\"settings_ask\",\"description\":\"Ask the human to change stam's settings (chief of staff and assistant only). Pass patch, an object of the keys to change, merged into the settings (a nested object merges per key; fill:true only fills keys that are unset). This sends the human a settings-change approval with a diff and returns the request id; nothing is written until the human approves, and then stam applies the patch itself, unless a setting it changes has changed since you asked (then ask again; other settings changing doesn't matter). Read the current settings first with the settings GET (secrets show as REDACTED). Other agents are refused: ask your chief of staff. When it reaches your user it goes in its home thread, so they see it with its work: the thread of `thread` (the mail it arose from), else the thread of `itsa`, else of the one active ITSA you own. With none of these it goes in a new thread; pass `override` with a one-line reason when no thread or ITSA fits. A `thread` or `itsa` you can't read is refused.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"patch\":{\"type\":\"object\",\"description\":\"The settings keys to change, such as {\\\"instructions\\\":{\\\"summaries\\\":{\\\"model\\\":\\\"claude-haiku-5-5\\\"}}}.\"},\"fill\":{\"type\":\"boolean\",\"description\":\"Only set keys that are not set yet.\"},\"thread\":{\"type\":\"string\",\"description\":\"The id of the mail this ask arose from, one you can read: the ask goes in that thread.\"},\"itsa\":{\"type\":\"string\",\"description\":\"The ITSA it is for (key or id): the ask goes in that ITSA's thread when you pass no thread. Without it, the one active ITSA you own.\"},\"override\":{\"type\":\"string\",\"description\":\"Only when no thread or ITSA fits: a one-line reason to send it in a new thread. Your user sees the reason.\"}},\"required\":[\"patch\"]}}"},
	{"cost", "", "{\"name\":\"usage_info\",\"description\":\"Spend and tokens by day, model, and agent, and subscription windows (such as Claude 5-hour and weekly limits), with estimated shares of each window by agent and tree, the usual percent per hour by hour of day and weekday, and when it reaches 100% (at the rate of the last 30 minutes, and following the usual pattern), the trees' allocations with their current use, plus the user's cost instructions. Compact by default (the windows with their projections, the top 5 trees, agents and models, the allocations, the machines); pass detail (true) for every agent, tree, model and cost unit with the hourly history, about 1 MB. Pass tree (an agent name or id) for that tree's estimated share and hourly history of each window, its allocations, and what a finished issue with its root's harness and model typically used. Use it to plan cost-aware work, for example picking a cheaper preset. It also includes machines: each computer's one-minute CPU, RAM, and swap averages, load, and its agents by state (null from a peer on an older release), to schedule work by load.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"days\":{\"type\":\"number\"},\"tree\":{\"type\":\"string\",\"description\":\"An agent name or id: show its tree's estimated share of each window.\"},\"detail\":{\"type\":\"boolean\",\"description\":\"The whole route answer, about 1 MB, not the compact one. False by default.\"}}}}"},
	{"cost", "", "{\"name\":\"activity_info\",\"description\":\"The activity summary of a scope, compact by default: the clock in hours (working, friction, others, you, idle); the tiles (cost and cost per working hour, in the display mode of settings.cost.display, with its unit, and API $); the top 5 bottlenecks (what slows work most, with the agents hit and the longest span); the top 5 categories; the closed work issues by model and type, with their medians; and the trees' roots. Scope is tree:NAME, itsa:S-N, or agent:NAME (default: you). With compare (default true), a typical block gives the median per closed work issue (cost, working time, lead time, review rounds) for your type and model across the fleet you may see, beside the scope's own medians; the fleet is dropped when it equals the scope. Use it for a retro on your own work or a finished ITSA (what was slow, what it cost, against typical), for a manager tuning its tree's cost and time, and for the chief of staff scheduling work by where time goes. Ask for detail (true) only when you need the whole summary: every leaf and every cost mode, about 25 KB. Days is the window, 7 by default. It covers the agents of every machine; machines.missing names a machine that did not answer (its agents are left out).\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"scope\":{\"type\":\"string\",\"description\":\"tree:NAME, itsa:S-N, or agent:NAME. Default: you (agent:YOU).\"},\"days\":{\"type\":\"number\",\"description\":\"The window in days, 7 by default.\"},\"compare\":{\"type\":\"boolean\",\"description\":\"Add the typical block for your type and model. True by default.\"},\"detail\":{\"type\":\"boolean\",\"description\":\"The whole summary (every leaf and cost mode, about 25 KB), not the compact one. False by default.\"}}}}"},
	{"cost", "", "{\"name\":\"cost_allocate\",\"description\":\"Set or clear an allocation on a tree: how much of an account's subscription window (kind 'window' with a percent), or how many paid dollars per period (kind 'usd' with an amount and a period of day, week, or month), the tree may use. The user sets any allocation, the chief of staff any, every other agent only trees inside its own tree. Allocations are not enforced: at 80% and 100% of an allocation the tree's manager and its root get a cost notice. Setting one that pushes children past their parent tree's allocation warns but is not refused. Pass clear: true (with id, or tree/account/kind/scope) to remove one.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"tree\":{\"type\":\"string\",\"description\":\"The tree's root agent, by id or name.\"},\"account\":{\"type\":\"string\",\"description\":\"The cost account, such as claude or openrouter.\"},\"kind\":{\"type\":\"string\",\"enum\":[\"window\",\"usd\"]},\"window\":{\"type\":\"string\",\"description\":\"For kind 'window': the window name, such as five_hour.\"},\"percent\":{\"type\":\"number\",\"description\":\"For kind 'window': the allocated percentage of the window.\"},\"amount\":{\"type\":\"number\",\"description\":\"For kind 'usd': the allocated dollars.\"},\"period\":{\"type\":\"string\",\"enum\":[\"day\",\"week\",\"month\"],\"description\":\"For kind 'usd': the period.\"},\"note\":{\"type\":\"string\",\"description\":\"Optional note, carried in the notices.\"},\"clear\":{\"type\":\"boolean\",\"description\":\"Remove the matching allocation instead of setting one.\"},\"id\":{\"type\":\"string\",\"description\":\"With clear: the allocation id.\"}}}}"},
	{"cost", "", "{\"name\":\"cost_ack\",\"description\":\"Record that you handled a cost notice, keyed by the event id in the notice. It stops the fallback timer for that event (the timer itself comes later). A manager calls this after it acts on a notice about its tree.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"event\":{\"type\":\"string\",\"description\":\"The event id from the cost notice, for example cn-1a2b3c4d.\"}},\"required\":[\"event\"]}}"},
	{"cost", "", "{\"name\":\"cost_switch\",\"description\":\"Move an agent's work to another preset, for example when its account is exhausted. The agent gets time to finish its step and update HANDOVER.md (cost.softStopMinutes, default 10), then stam stops its harness (keeping its session) and holds it as taken over. A successor NAME-t2 starts on the preset in the same workspace, with the same parents, the agent's children, open threads and unread mail, and mail to the old name goes to it. Refused when the preset's account is blocked. A manager may switch agents in its own tree; the chief of staff and the human any. The predecessor's open cost notices are acknowledged. A working agent switches in the background and you hear the outcome.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"agent\":{\"type\":\"string\",\"description\":\"The agent whose work moves: an id or name.\"},\"preset\":{\"type\":\"string\",\"description\":\"The preset to move it to; registry_info lists them.\"},\"soft_stop_minutes\":{\"type\":\"number\",\"description\":\"Minutes the agent gets to finish its step before stam interrupts it. Defaults to cost.softStopMinutes.\"}},\"required\":[\"agent\",\"preset\"]}}"},
	{"cost", "", "{\"name\":\"cost_pause\",\"description\":\"Pause a tree for cost until one of its subscription windows resets, or until a set time; stam lifts the pause by itself. Pass until=\\\"reset\\\" (with an account and window; the default window is the one closest to 100% on the tree's account) or an ISO 8601 time. Pass clear:true to lift an earlier cost pause early. The tree is the agent you name and everything below it, and agents spawned into it while it is paused are held too. A manager may pause its own tree; the chief of staff and the human may pause any. Calling this also acknowledges the tree's open cost notices.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"tree\":{\"type\":\"string\",\"description\":\"The tree root: an agent id or name.\"},\"until\":{\"type\":\"string\",\"description\":\"\\\"reset\\\", or an ISO 8601 time such as 2026-10-12T09:00:00Z.\"},\"account\":{\"type\":\"string\",\"description\":\"For until=reset: the cost account. Defaults to the tree's account.\"},\"window\":{\"type\":\"string\",\"description\":\"For until=reset: the window, for example five_hour. Defaults to the window closest to 100%.\"},\"clear\":{\"type\":\"boolean\",\"description\":\"Remove the tree's cost pause early, instead of setting one.\"},\"reason\":{\"type\":\"string\",\"description\":\"Why, for the resume notice and the record.\"}},\"required\":[\"tree\"]}}"},
	{"mail", "", "{\"name\":\"send_mail\",\"description\":\"Send mail to one or more agents by id or name, to \\\"all\\\", or to \\\"human\\\" (your user). Mail works like Slack threads: an answer to a mail joins its thread. Pass the mail's id as reply_to to be sure; without it, an answer to mail you just read joins that thread anyway (if you read several threads in the last 30 minutes and don't name one, the daemon errors listing them, so pass reply_to). For a new topic, pass new_thread: true. A reply reaches your user only when `to` names \\\"human\\\", in their own threads too. Bodies render as Markdown. Before mailing \\\"human\\\", search for the relevant thread with search_mail and read it: if one exists, reply in it with reply_to; if unsure, ask your parent. A new thread is fine when none fits, but continuing an existing one is preferred. Mail to \\\"human\\\" is only for what your user must decide or read (see your instructions); mail between agents has no such rules. The body holds about 5,000 tokens; longer text becomes an attachment. Attach files by path or inline content.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"to\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"subject\":{\"type\":\"string\",\"description\":\"Required for a new thread; optional with reply_to.\"},\"body\":{\"type\":\"string\"},\"reply_to\":{\"type\":\"string\",\"description\":\"Id of the mail this answers.\"},\"supersedes\":{\"type\":\"string\",\"description\":\"The exact id of an earlier mail of yours that this one replaces, after you find it was wrong. The old mail stays in its thread, but leaves inboxes, unread counts and notifications, and its ask to your user is withdrawn. Only your own mail, by exact id.\"},\"itsa\":{\"type\":\"string\",\"description\":\"The ITSA (key such as S-12, or id) this mail is about: the web UI shows it as a chip in the mail header. Mail in an ITSA's own thread is about that ITSA already.\"},\"new_thread\":{\"type\":\"boolean\",\"description\":\"Start a new thread. Without it, an answer to a mail you just read joins that mail's thread.\"},\"override\":{\"type\":\"string\",\"description\":\"Only for mail to \\\"human\\\": a mail check refuses a mail your user doesn't need or that breaks the rules for mail to them. If you disagree, resend with the reason here; the mail goes out and your user sees the reason.\"},\"attachments\":{\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"path\":{\"type\":\"string\"},\"name\":{\"type\":\"string\"},\"content\":{\"type\":\"string\"}}}}},\"required\":[\"to\",\"body\"]}}"},
	{"mail", "", "{\"name\":\"mail_attach\",\"description\":\"Attach ITSAs and agents to an existing mail, silently: the web UI shows them as chips in its header. It sends no mail, makes no notice and no unread state. Use it instead of replying when all you would say is which ITSA or agent handles a request. Only a recipient of the mail, or the chief of staff, may attach.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"mail_id\":{\"type\":\"string\",\"description\":\"The id of the mail to attach to.\"},\"itsas\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"ITSA keys (S-12) or ids.\"},\"agents\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Agent names or ids.\"}},\"required\":[\"mail_id\"]}}"},
	{"mail", "", "{\"name\":\"withdraw_ask\",\"description\":\"Withdraw your ask from your user when it no longer needs them: answered another way, or moot.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"mail_id\":{\"type\":\"string\",\"description\":\"The id of your decision mail to the human.\"},\"note\":{\"type\":\"string\",\"description\":\"Why, in a few words, for example \\\"answered in the terminal\\\".\"}},\"required\":[\"mail_id\",\"note\"]}}"},
	{"agents", "", "{\"name\":\"spawn_agent\",\"description\":\"Start a new agent as your child: it is registered under you, you get its status and blockers, and you can control it with agent_control. Any model name works, even one stam does not know yet. The executive assistant can also start it under any parent or none, or as chief of staff. A developer spawn when the machine already runs developerCap developers (settings, default 6) is not refused but queued: you get \\\"queued, place N\\\" with the holders, the agent starts by itself when a slot frees (first come first served), and you get a notice when it does or fails. Keep working meanwhile; do not spawn it again. Reviewers and other types are never queued. To let the child comment on or join an ITSA without owning it, pass participate with its ids or keys; the spawn is refused before anything starts if you may not add participants to one.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"name\":{\"type\":\"string\",\"description\":\"Unique lowercase name with dashes.\"},\"role\":{\"type\":\"string\",\"description\":\"What it is for. Defaults to its type.\"},\"prompt\":{\"type\":\"string\",\"description\":\"Its first task. With a type that has a brief, this is the brief's {{task}}.\"},\"type\":{\"type\":\"string\",\"description\":\"An agent type from registry_info, such as \\\"developer\\\", \\\"reviewer\\\", or \\\"manager\\\": sets its harness, model, effort, role, standing instructions, brief, and worktree default. Explicit fields override it. A reviewer type follows its fallback chain when its account is held. A ring reviewer type (no harness, model, or preset allowed) starts a ring named NAME: members NAME-1, NAME-2, ... and a moderator NAME-mod, with your prompt as the topic; its result is mailed to you, and if a member can't start, the type's fallback runs as a single reviewer.\"},\"brief_vars\":{\"type\":\"object\",\"additionalProperties\":{\"type\":\"string\"},\"description\":\"Extra values for placeholders in the type's brief.\"},\"preset\":{\"type\":\"string\",\"description\":\"A preset from registry_info, such as \\\"fast\\\" or \\\"deep\\\". Sets harness, model, and effort.\"},\"harness\":{\"type\":\"string\",\"description\":\"\\\"claude\\\" (default), \\\"opencode\\\", or \\\"codex\\\".\"},\"model\":{\"type\":\"string\"},\"effort\":{\"type\":\"string\"},\"cwd\":{\"type\":\"string\",\"description\":\"Directory to work in, or the repo for a worktree. Defaults to yours.\"},\"machine\":{\"type\":\"string\",\"description\":\"Machine to run it on, from the machine field in find_agents. Defaults to yours.\"},\"worktree\":{\"type\":\"boolean\",\"description\":\"Give it its own git worktree and branch, removed when it is archived. Defaults to the type's worktree default (the developer type is true). A developer that ends up without one in the live deploy checkout is refused, since its commits there would hold every deploy.\"},\"base\":{\"type\":\"string\",\"description\":\"A git ref to cut the worktree's branch from, such as origin/stam/x (fetched first; a local branch works too). The spawn fails if it does not resolve. Without it, a repo with an origin remote is cut from a freshly fetched origin/main (falling back to the checkout's HEAD if the fetch fails; the spawn's workspace:base event says which). A base of origin/stam/X (or storage/stam/X) continues that PR: the worktree goes on stam/X itself at the base's commit, so pr_open updates the PR with no fast-forward (the spawn result and the workspace:base event say so). The spawn is refused when stam/X is checked out in another worktree (archive its holder) or a local stam/X has commits the base lacks. To stack a NEW PR on stam/X instead, pass branch: \\\"new\\\" (a reviewer type always gets its own branch). Only with a worktree.\"},\"branch\":{\"type\":\"string\",\"description\":\"The worktree's branch name. Defaults to stam/NAME, or to the PR branch itself when base is origin/stam/X. Pass a new name, or \\\"new\\\" for stam/NAME, to cut a new branch (a stacked PR) from that base instead of continuing it. An explicit name is used as given. When the default stam/NAME is already taken (here or on origin), the branch gets a free -2, -3 suffix; the spawn result and the agent's brief name it. Only with a worktree.\"},\"workspace_script\":{\"type\":\"string\",\"description\":\"Shell command that prints the directory to work in.\"},\"workspace_instructions\":{\"type\":\"string\",\"description\":\"Tell it to create its own workspace this way.\"},\"standing\":{\"type\":\"boolean\",\"description\":\"A long-lived specialist, kept as a standing agent rather than one for a single task. A standing agent idle for standing.idleHours (default 4) rests, harness stopped, and mail, a fired wake_me or an assigned ITSA wakes it.\"},\"workspace\":{\"type\":[\"boolean\",\"string\"],\"description\":\"A personal workspace folder for this agent, at STAM_HOME/workspaces/NAME, separate from its working directory and kept when it is archived. true uses the agent's own name; a string names a workspace (lowercase letters, digits, and dashes), so a respawned specialist can adopt an archived one's folder. Never a git repo or worktree.\"},\"visibility\":{\"type\":\"object\",\"description\":\"Whom the child may reach. reach: \\\"all\\\" (default), \\\"tree\\\", or \\\"parent\\\"; siblings: may it mail its siblings; registry: may it see the whole registry.\",\"properties\":{\"reach\":{\"type\":\"string\",\"enum\":[\"all\",\"tree\",\"parent\"]},\"siblings\":{\"type\":\"boolean\"},\"registry\":{\"type\":\"boolean\"}}},\"child_notices\":{\"type\":\"string\",\"enum\":[\"turn\",\"tree-idle\",\"none\"],\"description\":\"How much this child hears about its own children's finished turns: 'tree-idle' (default), 'turn', or 'none'. Blocked and errored agents always reach their parents.\"},\"urgent\":{\"type\":\"string\",\"enum\":[\"red-main\",\"deploy-hold\",\"approved-pr\",\"incident\"],\"description\":\"Only for a developer spawn that has to queue because the slots are full: the reason it should go ahead of normal spawns (first come first served within each class). red-main: a fix for a red main; deploy-hold: a fix that clears a deploy hold; approved-pr: a fix on an approved PR; incident: a fix for an incident, which goes ahead like red-main only when its itsa (or one of that ITSA's parents) is marked an incident by the chief of staff or the human (itsa_set incident=true), and is refused otherwise. On another machine the ITSA home is asked for the mark, and the spawn is refused unless it says yes. Not for anything else.\"},\"itsa\":{\"type\":\"string\",\"description\":\"An ITSA id or key: the new agent becomes its owner (a reviewer type joins as a participant instead, and the owner stays), and its first prompt carries the ITSA (key, title, summary, body, parent chain, links). With no prompt, that block is the prompt.\"},\"participate\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"ITSA ids or keys the new agent joins as a participant, without owning them: it can comment and change them, and the owner stays. You must be allowed to add participants to each (an owner, a participant, or an owner of a parent ITSA). If you are not, the spawn is refused and nothing starts.\"},\"parent\":{\"type\":\"string\",\"description\":\"Executive assistant only: the parent agent, or \\\"none\\\" for a top-level agent. Defaults to you.\"},\"chief_of_staff\":{\"type\":\"boolean\",\"description\":\"Executive assistant only: make it the chief of staff.\"}},\"required\":[\"name\"]}}"},
	{"agents", "", "{\"name\":\"agent_control\",\"description\":\"Control yourself or one of your children: pause, unpause, shutdown, archive (shut down and remove its worktree), resume, restart, reconnect-mcp, set-visibility, set-child-notices (how much you hear about your children's finished turns: \\\"turn\\\", \\\"tree-idle\\\", or \\\"none\\\"; blocked and errored children always reach you). cancel removes a developer spawn that is still queued for a slot, by its name in agent (not an agent yet, so no agent id): its caller, the caller's parents, and the chief of staff may cancel it; a spawn already granted a slot is refused, and a name that isn't queued is a 404. Cancel finds the spawn on whichever machine queued it and forwards to that machine; there, the caller's parents can cancel only when that machine knows the caller (otherwise only the caller and the chief of staff can), and an unreachable machine gives a 502, not a 404. The chief of staff can also adopt any agent as its parent. Shutdown, archive, and restart wait until the agent finishes its current step. Every archive asks the agent for its final retro round and waits for its next turn end, bounded by settings.archive.finalRoundMinutes (default 3); a wrap-up pushed while the agent runs a step can get one more turn, with a fresh finalRoundMinutes deadline, because the harness may hold it for the next turn; archive with force only skips the turn-alive check for an agent whose harness is gone, and archive with discard removes uncommitted worktree changes. The executive assistant controls every agent, and alone can also set-parent (parent: an agent, or \\\"none\\\" for top-level), rename (name), make one chief-of-staff, kill (stop now), and forget (remove a stopped agent from the registry).\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"agent\":{\"type\":\"string\",\"description\":\"Id or name of the agent.\"},\"action\":{\"type\":\"string\",\"enum\":[\"pause\",\"unpause\",\"shutdown\",\"archive\",\"resume\",\"restart\",\"reconnect-mcp\",\"adopt\",\"set-visibility\",\"set-child-notices\",\"set-parent\",\"rename\",\"chief-of-staff\",\"kill\",\"forget\",\"cancel\"]},\"note\":{\"type\":\"string\",\"description\":\"For resume and restart: a note the agent receives.\"},\"force\":{\"type\":\"boolean\",\"description\":\"For archive: do not wait for the agent's current step. A forced pending archive whose harness is gone runs at once, skipping the turn-alive check; it still asks the agent for its final round, bounded by settings.archive.finalRoundMinutes, and a forced archive of a live agent waits for that extra turn too. It also discards uncommitted worktree changes. For unpause: clear its cost blockers too.\"},\"force_unpushed\":{\"type\":\"boolean\",\"description\":\"For archive: archive although the branch has commits that are on no remote (the archive is refused otherwise, naming the branch, the count and the head; push it or pr_open first). The commits stay on the local branch, which the archive keeps.\"},\"discard\":{\"type\":\"boolean\",\"description\":\"For archive: discard the agent's uncommitted worktree changes. Every archive asks the agent for its final retro round and waits for its next turn end, at most settings.archive.finalRoundMinutes (default 3), before archiving.\"},\"visibility\":{\"type\":\"object\",\"description\":\"For set-visibility: same shape as in spawn_agent.\"},\"child_notices\":{\"type\":\"string\",\"enum\":[\"turn\",\"tree-idle\",\"none\"],\"description\":\"For set-child-notices: how much you hear about your children's finished turns.\"},\"parent\":{\"type\":\"string\",\"description\":\"For set-parent: the new parent, or \\\"none\\\".\"},\"name\":{\"type\":\"string\",\"description\":\"For rename: the new name.\"}},\"required\":[\"agent\",\"action\"]}}"},
	{"agents", "", "{\"name\":\"compact_self\",\"description\":\"Compact your own conversation when you end your current turn. Say what the summary must keep, and give a prompt you will receive right after compaction so you can continue.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"instructions\":{\"type\":\"string\",\"description\":\"What the summary must keep.\"},\"prompt_after\":{\"type\":\"string\",\"description\":\"The prompt you receive after compaction.\"}},\"required\":[\"instructions\",\"prompt_after\"]}}"},
	{"permissions", "", "{\"name\":\"request_permission\",\"description\":\"Ask for permission when something you need is blocked or needs consent. `audience` is `human` when only your user's consent unblocks it: a harness or auto-mode safety block, an irreversible or outward action, spend above the caps. `delegate` when your parent or the chief of staff can decide it; they escalate to your user if needed. If omitted, it goes to your parent or the chief of staff, or to your user when you have neither. A delegate ask with no parent or chief of staff to decide goes to your user. The answer arrives as a stam notice saying who answered. Keep working on other things meanwhile. When it reaches your user it goes in its home thread, so they see it with its work: the thread of `thread` (the mail it arose from), else the thread of `itsa`, else of the one active ITSA you own. With none of these it goes in a new thread; pass `override` with a one-line reason when no thread or ITSA fits. A `thread` or `itsa` you can't read is refused.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"action\":{\"type\":\"string\",\"description\":\"What you need to do, in one line.\"},\"reason\":{\"type\":\"string\",\"description\":\"Why it is needed for your task.\"},\"details\":{\"type\":\"string\",\"description\":\"The exact command or tool call, and what the check said.\"},\"audience\":{\"type\":\"string\",\"enum\":[\"human\",\"delegate\"],\"description\":\"'human': only your user's consent unblocks it. 'delegate': your parent or the chief of staff can decide it. Omit it to default to delegate.\"},\"thread\":{\"type\":\"string\",\"description\":\"The id of the mail this ask arose from, one you can read: the ask goes in that thread.\"},\"itsa\":{\"type\":\"string\",\"description\":\"The ITSA it is for (key or id): the ask goes in that ITSA's thread when you pass no thread. Without it, the one active ITSA you own.\"},\"override\":{\"type\":\"string\",\"description\":\"Only when no thread or ITSA fits: a one-line reason to send it in a new thread. Your user sees the reason.\"}},\"required\":[\"action\",\"reason\"]}}"},
	{"permissions", "", "{\"name\":\"suggest_input\",\"description\":\"Claude Code only. Suggest one line for your user to approve, which stam then types into your own input box exactly as written and sends, as if your user typed it: for example `! git push` to run a command auto mode blocked. Only the human can approve it, from stam's web UI; reviewing agents can only deny it. A suggestion waits until your user answers it or it is withdrawn, and a new suggestion replaces your pending one. Once approved, it waits 30 minutes for your input box to be free, and expires after that. The answer arrives as a stam notice: typed, held until your input box is free, or expired. When it reaches your user it goes in its home thread, so they see it with its work: the thread of `thread` (the mail it arose from), else the thread of `itsa`, else of the one active ITSA you own. With none of these it goes in a new thread; pass `override` with a one-line reason when no thread or ITSA fits. A `thread` or `itsa` you can't read is refused.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"text\":{\"type\":\"string\",\"description\":\"The exact line to type: one line, no control characters, at most 2000 characters.\"},\"reason\":{\"type\":\"string\",\"description\":\"Why you need it, for your user.\"},\"thread\":{\"type\":\"string\",\"description\":\"The id of the mail this ask arose from, one you can read: the ask goes in that thread.\"},\"itsa\":{\"type\":\"string\",\"description\":\"The ITSA it is for (key or id): the ask goes in that ITSA's thread when you pass no thread. Without it, the one active ITSA you own.\"},\"override\":{\"type\":\"string\",\"description\":\"Only when no thread or ITSA fits: a one-line reason to send it in a new thread. Your user sees the reason.\"}},\"required\":[\"text\",\"reason\"]}}"},
	{"permissions", "", "{\"name\":\"answer_permission\",\"description\":\"Answer a permission request from one of your children (or any agent, if you are the chief of staff or the executive assistant). decision: approve, deny, or escalate (send it to the human, with a one-line reason in note). Never leave a request waiting. You can only deny or escalate a harness dialog (Claude Code asks to allow ...), and only deny a request whose audience is human; the human approves those.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"id\":{\"type\":\"string\"},\"decision\":{\"type\":\"string\",\"enum\":[\"approve\",\"deny\",\"escalate\"]},\"approve\":{\"type\":\"boolean\",\"description\":\"Older form of decision: true approves, false denies.\"},\"note\":{\"type\":\"string\",\"description\":\"Your reasoning, passed to the requester. For escalate: the one-line reason the human reads.\"}},\"required\":[\"id\",\"note\"]}}"},
	{"ring", "", "{\"name\":\"ring_create\",\"description\":\"Start a ring: several agents work on one topic together, best with models from different companies. format: \\\"rounds\\\" (all answer in parallel, then all read all), \\\"fire\\\" (one at a time, each sees everything before), or \\\"debate\\\". Name existing agents as members, or spawn new ones in spawn: each entry is { type: NAME } (an agent type from registry_info; a reviewer type follows its fallback chain when its account is held), { preset }, or { harness, model }. Optional moderator: an existing agent, or { type: NAME } (or { preset }) to spawn one named NAME-mod; it only facilitates or also decides. If the ring can't start, the agents spawned for it are archived. The result is mailed to you.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"name\":{\"type\":\"string\",\"description\":\"Unique lowercase name with dashes; spawned members are named NAME-1, NAME-2, ...\"},\"topic\":{\"type\":\"string\"},\"format\":{\"type\":\"string\",\"enum\":[\"rounds\",\"fire\",\"debate\"]},\"members\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Existing agents, by id or name.\"},\"spawn\":{\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"type\":{\"type\":\"string\"},\"preset\":{\"type\":\"string\"},\"harness\":{\"type\":\"string\"},\"model\":{\"type\":\"string\"}}},\"description\":\"New members to spawn, by agent type, preset, or harness and model.\"},\"moderator\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"object\",\"properties\":{\"type\":{\"type\":\"string\"},\"preset\":{\"type\":\"string\"},\"harness\":{\"type\":\"string\"},\"model\":{\"type\":\"string\"}}}],\"description\":\"An existing agent (id or name) that reads each round, or an object like a spawn entry to spawn one.\"},\"moderator_decides\":{\"type\":\"boolean\",\"description\":\"The moderator ends the ring with a decision, instead of only facilitating.\"},\"max_rounds\":{\"type\":\"number\"}},\"required\":[\"name\",\"topic\",\"format\"]}}"},
	{"ring", "", "{\"name\":\"ring_submit\",\"description\":\"Submit your contribution to a ring you were prompted in. Set agree to true only if you accept the current state as final. In a ring that reviews a PR, give your verdict too: the ring ends early only when every member's verdict is the same.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"ring\":{\"type\":\"string\"},\"text\":{\"type\":\"string\"},\"agree\":{\"type\":\"boolean\"},\"verdict\":{\"type\":\"string\",\"enum\":[\"approve\",\"request_changes\"],\"description\":\"Your verdict on the PR, in a ring that reviews one. Left out, stam reads it from your text.\"},\"round\":{\"type\":\"number\",\"description\":\"The round your turn prompt shows (\\\"round N of at most M\\\"). A submit for a round the ring has moved past is refused and writes nothing. Left out, it goes to the ring's current round.\"},\"seat\":{\"type\":\"string\",\"description\":\"The member the text is for, by the name your turn prompt shows (\\\"You are NAME\\\"). Required when you hold two or more open seats in the ring, such as your own and a predecessor's; a seat you don't hold is refused; one already filled this round is rewritten (rounds rings). Left out, the text goes to your one open seat.\"}},\"required\":[\"ring\",\"text\",\"agree\"]}}"},
	{"ring", "", "{\"name\":\"ring_decide\",\"description\":\"As a ring's moderator, after a round: continue with a note for the members, or end the ring (with your decision, if you decide).\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"ring\":{\"type\":\"string\"},\"continue\":{\"type\":\"boolean\"},\"text\":{\"type\":\"string\"}},\"required\":[\"ring\",\"continue\",\"text\"]}}"},
	{"agents", "", "{\"name\":\"reconnect_mcp\",\"description\":\"Reconnect your own MCP servers. In some harnesses this restarts you and resumes your conversation after your current step.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"}}}}"},
	{"mail", "", "{\"name\":\"defer_thread\",\"description\":\"Set one of your mail threads aside for later: it leaves your unread count and your list, and comes back when new mail arrives in it. Not archived. Pass undo: true to bring it back now.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"thread_id\":{\"type\":\"string\",\"description\":\"The thread to defer.\"},\"undo\":{\"type\":\"boolean\",\"description\":\"Bring a deferred thread back (default false).\"}},\"required\":[\"thread_id\"]}}"},
	{"mail", "", "{\"name\":\"list_inbox\",\"description\":\"List your mail, newest first, without bodies.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"unread_only\":{\"type\":\"boolean\"},\"limit\":{\"type\":\"number\"}}}}"},
	{"mail", "", "{\"name\":\"read_mail\",\"description\":\"Read mail and mark it read. Without ids, reads up to 10: mail whose earlier read got no reply first (not FYI or system mail, nor mail over 6 hours old), then unread mail, oldest first.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"ids\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}}}}}"},
	{"waits", "", "{\"name\":\"wait_for\",\"description\":\"Declare that you are waiting: stam shows you as waiting and holds your parent's finished-turn notice until it clears. on: 'agent' (with target, an agent id or name) or 'human' for a reply, or 'event' (with filter) for an external event. A reply wait clears when the mail arrives — for 'agent', mail from that agent to you (in `thread` if you name a mail id); for 'human', mail from your user. An event wait clears on the first event a source posts that fits filter (source, subjects, types, actors; subject and type patterns are globs, such as `github:OWNER/REPO#12`), and you get that event as a notice. Optional timeout_minutes: when it elapses the wait clears and you get a notice. If you can't continue until your user answers an ask, call `wait_for` with `on:'human'` and `thread` set to the ask's mail id. A wait on 'human' while your own permission request is pending with your user is about that request: it clears when the request is answered or closed, so a request needs no wait of its own. Returns the wait id, for wait_done.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"on\":{\"type\":\"string\",\"enum\":[\"agent\",\"human\",\"event\"],\"description\":\"What you wait for.\"},\"target\":{\"type\":\"string\",\"description\":\"An agent id or name, for on 'agent'.\"},\"thread\":{\"type\":\"string\",\"description\":\"A mail id: clear only for mail in that mail's thread.\"},\"filter\":{\"type\":\"object\",\"description\":\"For on 'event' (required): which events clear the wait. Name at least one of source, subjects, types or actors; an empty filter is refused.\",\"properties\":{\"source\":{\"type\":\"string\",\"description\":\"Such as github or linear.\"},\"subjects\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Subject keys, such as github:OWNER/REPO#12; * is a glob within one segment.\"},\"types\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Event types, such as pull_request.synchronize.\"},\"actors\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Who the event is about.\"}}},\"timeout_minutes\":{\"type\":\"number\",\"description\":\"Give up after this many minutes.\"},\"expect_minutes\":{\"type\":\"number\",\"description\":\"Optional: about how many minutes until you expect the answer. Nothing fires then; it tells stam how long you will likely wait, so a long wait lets your harness rest until the answer wakes you.\"},\"note\":{\"type\":\"string\",\"description\":\"What you wait for, shown as your wait detail.\"},\"rest\":{\"type\":\"boolean\",\"description\":\"Optional: true asks stam to stop your harness as soon as this turn ends, instead of after the usual idle minutes, to free its memory; the answer, mail or a notice wakes you, with your conversation resumed. Pass it for a long wait with nothing to do meanwhile; leave it out when you expect an answer within minutes. stam keeps you up anyway while something still needs you.\"}},\"required\":[\"on\"]}}"},
	{"waits", "", "{\"name\":\"wait_done\",\"description\":\"Clear one of your own waits declared with wait_for or scheduled with wake_me, by its id. Cron and periodic timers stay until you clear them this way.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"id\":{\"type\":\"string\",\"description\":\"The wait id from wait_for or wake_me.\"}},\"required\":[\"id\"]}}"},
	{"waits", "", "{\"name\":\"wake_me\",\"description\":\"Schedule a wake-up: stam sends your note back to you as a notice later (a prompt if you are idle). Exactly one schedule: in_minutes (once, N minutes from now), at (once, an ISO time), every_minutes (repeated every N minutes), or cron (a 5-field cron: minute hour day-of-month month day-of-week). A one-off wake clears when it fires; a cron or periodic one fires each time and stays until wait_done. Returns the wait id.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"in_minutes\":{\"type\":\"number\",\"description\":\"Once, this many minutes from now.\"},\"at\":{\"type\":\"string\",\"description\":\"Once, at this ISO 8601 time.\"},\"every_minutes\":{\"type\":\"number\",\"description\":\"Repeated, every this many minutes.\"},\"cron\":{\"type\":\"string\",\"description\":\"Repeated, on a 5-field cron schedule.\"},\"note\":{\"type\":\"string\",\"description\":\"What to send back when it fires.\"},\"rest\":{\"type\":\"boolean\",\"description\":\"Optional: true asks stam to stop your harness as soon as this turn ends, instead of after the usual idle minutes, to free its memory; the wake-up, mail or a notice wakes you, with your conversation resumed. Pass it for a long wait with nothing to do meanwhile; leave it out when it fires within minutes. stam keeps you up anyway while something still needs you.\"}},\"required\":[\"note\"]}}"},
	{"mail", "", "{\"name\":\"read_thread\",\"description\":\"Read a mail thread you take part in, oldest first: the messages you sent or received in it. Also a thread with your user that one of your parents took part in, found with search_mail, and the threads of an ITSA you own or take part in, or whose parent ITSA you own. thread_id may be any mail id in the thread, such as one cited in your brief. Doesn't mark anything read.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"thread_id\":{\"type\":\"string\"}},\"required\":[\"thread_id\"]}}"},
	{"mail", "", "{\"name\":\"search_mail\",\"description\":\"Search mail by keyword: your own mail, and the threads with your user that your parents (and their parents) took part in. Returns one line per thread, best first. Search before you mail your user, to find the thread to answer. \\\"with\\\" limits the results to threads an agent or \\\"human\\\" takes part in. To search ITSAs too, and to match by meaning, use search.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"query\":{\"type\":\"string\",\"description\":\"Words to match in subjects and bodies.\"},\"with\":{\"type\":\"string\",\"description\":\"An agent name or id, or \\\"human\\\": only threads that one takes part in.\"},\"limit\":{\"type\":\"number\",\"description\":\"Threads to return. Defaults to 10, at most 30.\"}},\"required\":[\"query\"]}}"},
	{"mail", "", "{\"name\":\"search\",\"description\":\"Search by meaning across mail and ITSAs, in one list, best first: the mail search_mail finds (your own, and the threads with your user that your parents took part in) and every ITSA. Each line is tagged [mail] or [itsa]. Words need not match the title: a query worded differently still finds the thread or ITSA about it.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"query\":{\"type\":\"string\",\"description\":\"What to look for, in any words.\"},\"kinds\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"enum\":[\"mail\",\"itsa\"]},\"description\":\"What to search: mail, itsa, or both. Defaults to both.\"},\"limit\":{\"type\":\"number\",\"description\":\"Results to return. Defaults to 10, at most 30.\"}},\"required\":[\"query\"]}}"},
	{"itsas", "", "{\"name\":\"itsa_create\",\"description\":\"Create an ITSA: a nestable, tracked piece of work (initiative, project, milestone, or issue are only a kind label; any ITSA can hold children). You join as a participant only when you are its owner. Returns its readable key like S-42. ITSAs are optional.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"title\":{\"type\":\"string\",\"description\":\"Required. 1-4 words, a noun phrase that names the thing, like `Phone mail header`: no sentence, no colon, no parent key. The one-line detail goes in summary.\"},\"summary\":{\"type\":\"string\",\"description\":\"One-line description.\"},\"body\":{\"type\":\"string\",\"description\":\"Markdown body.\"},\"parent\":{\"type\":\"string\",\"description\":\"Parent ITSA by id or key. Omit for a root.\"},\"kind\":{\"type\":\"string\",\"description\":\"A label: initiative, project, milestone, issue, or proposal. An ITSA answering retro items (an Answers: line under Retros, or a retro steward's) with an instruction or template edit (a diff touching blocks/, templates/, CLAUDE.md, AGENTS.md, or registry/) must be proposal; a code fix answering retro items may be an issue.\"},\"status\":{\"type\":\"string\",\"description\":\"A status name; defaults to backlog.\"},\"owner\":{\"type\":\"string\",\"description\":\"An agent id or name, or \\\"human\\\". Defaults to nobody.\"},\"participants\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Agents or \\\"human\\\" to keep informed; the owner is always one.\"},\"links\":{\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"url\":{\"type\":\"string\"},\"system\":{\"type\":\"string\"},\"external_id\":{\"type\":\"string\"}},\"required\":[\"url\"]},\"description\":\"Links to external items (a PR, an issue, a URL).\"}},\"required\":[\"title\"]}}"},
	{"requirements", "requirements", "{\"name\":\"req_create\",\"description\":\"Write a requirement as a draft: a \\\"shall\\\" statement your user keeps and stam checks work against. It is always a draft; under the default approval setting your user approves it, and an ask reaches them (the result names the ITSA). Give a title and the shall text; a rationale and source say why it exists. verification is a list of methods (decision, test, pattern, review, human); scope narrows what it applies to. Returns its key like R-7.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"title\":{\"type\":\"string\",\"description\":\"Required: a short name.\"},\"text\":{\"type\":\"string\",\"description\":\"The \\\"shall\\\" statement, in the words of the person who wrote it. The model reads this text.\"},\"rationale\":{\"type\":\"string\",\"description\":\"Why it exists.\"},\"source\":{\"type\":\"string\",\"description\":\"Where it came from: CLAUDE.md:58, a mail id, the user's words.\"},\"parent\":{\"type\":\"string\",\"description\":\"The requirement it derives from, by key.\"},\"level\":{\"type\":\"string\",\"description\":\"A free label: stakeholder, system, subsystem, process.\"},\"severity\":{\"type\":\"string\",\"enum\":[\"info\",\"minor\",\"major\",\"critical\"]},\"mode\":{\"type\":\"string\",\"enum\":[\"observe\",\"inform\",\"enforce\"],\"description\":\"observe records only; inform tells the actor; enforce can also deny a tool call. Default observe.\"},\"threshold\":{\"type\":\"number\",\"description\":\"P(violates) needed to act, 0 to 1. Default 0.8.\"},\"verification\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Methods: decision (a model inspects every subject in scope), test, pattern, review, human.\"},\"scope\":{\"type\":\"object\",\"description\":\"What it applies to. Lists, any of: subjects (mail, mail-to-human, itsa, branch, tool, event, manual), paths (globs), repos, roles, agents, itsa (keys), tools, sources, types (event type globs such as pull_request.*).\"},\"owner\":{\"type\":\"string\",\"description\":\"An agent id or name, or \\\"human\\\": answers waivers and false-positive reports.\"}},\"required\":[\"title\"]}}"},
	{"requirements", "requirements", "{\"name\":\"req_get\",\"description\":\"Read requirements. With a key (R-7): the requirement, its trace (parents, children, links), and its recent verdicts with their numbers (for req_waive). Without one: the list, optionally filtered by status (draft, in_force, suspended, obsolete), parent (a key, or \\\"root\\\"), and text.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"key\":{\"type\":\"string\",\"description\":\"A requirement key like R-7. Omit to list.\"},\"status\":{\"type\":\"string\"},\"parent\":{\"type\":\"string\",\"description\":\"List only the children of this requirement, or \\\"root\\\".\"},\"text\":{\"type\":\"string\",\"description\":\"Words to find in keys, titles, texts, rationales, sources.\"}}}}"},
	{"requirements", "requirements", "{\"name\":\"req_set\",\"description\":\"Change a requirement: title, text, rationale, source, parent, level, severity, mode, threshold, verification, scope, owner, or status (draft, in_force, suspended, obsolete). A change to the text or scope makes a new version. Moving a requirement into in_force is the approval: the API refuses unless the approval setting allows you. An agent approving must pass if_rev (the rev in req_get and in the ask) and nothing else in that call, so it approves exactly what it read. Under human or cos approval an agent cannot change the text or scope of a requirement that is in force or suspended: create a new draft linked with role refines and mail the owner. Nor can it change the mode, threshold, or severity of such a requirement, nor approve text it last changed. Add links with add_links, remove them with remove_links.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"key\":{\"type\":\"string\",\"description\":\"Required: the requirement, like R-7.\"},\"title\":{\"type\":\"string\"},\"text\":{\"type\":\"string\"},\"rationale\":{\"type\":\"string\"},\"source\":{\"type\":\"string\"},\"parent\":{\"type\":\"string\",\"description\":\"A key, or \\\"root\\\".\"},\"level\":{\"type\":\"string\"},\"severity\":{\"type\":\"string\",\"enum\":[\"info\",\"minor\",\"major\",\"critical\"]},\"mode\":{\"type\":\"string\",\"enum\":[\"observe\",\"inform\",\"enforce\"]},\"threshold\":{\"type\":\"number\"},\"status\":{\"type\":\"string\",\"enum\":[\"draft\",\"in_force\",\"suspended\",\"obsolete\"]},\"owner\":{\"type\":\"string\"},\"verification\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"scope\":{\"type\":\"object\"},\"if_rev\":{\"type\":\"number\",\"description\":\"Refuse the change unless the requirement is at this rev (shown in req_get and in the approval ask): approve the draft you read, not one edited since.\"},\"add_links\":{\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"target\":{\"type\":\"string\"},\"target_kind\":{\"type\":\"string\",\"enum\":[\"itsa\",\"file\",\"test\",\"mail\",\"url\",\"requirement\"]},\"role\":{\"type\":\"string\",\"enum\":[\"implements\",\"verifies\",\"allocated_to\",\"refines\",\"conflicts_with\"]}},\"required\":[\"target\"]}},\"remove_links\":{\"type\":\"array\",\"items\":{\"type\":\"number\"},\"description\":\"Link numbers (#N in req_get).\"}},\"required\":[\"key\"]}}"},
	{"requirements", "requirements", "{\"name\":\"req_check\",\"description\":\"Check work against the requirements in scope, before you send mail or open a pull request: pass `text` (a draft mail, a body), or a subject: mail:ID, itsa:KEY, or branch:REPO/NAME (a branch's diff against main). Optionally keys limits it to named requirements. Returns a verdict per requirement: conforms, violates, na, or unsure. A verdict is an indication from a model, not proof; if one is wrong, record it with req_waive. Nobody is told by this call.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"text\":{\"type\":\"string\",\"description\":\"Text to check.\"},\"subject\":{\"type\":\"string\",\"description\":\"mail:ID, itsa:KEY, or branch:REPO/NAME.\"},\"keys\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Only these requirements, like [\\\"R-7\\\"].\"},\"preview\":{\"type\":\"boolean\",\"description\":\"Instead of checking a subject, run the requirements named in keys on the last n real subjects of their scope (recent mail, ITSAs, branches) and show what they would flag. Records nothing and tells nobody. Use it on a new or reworded requirement.\"},\"n\":{\"type\":\"number\",\"description\":\"With preview: how many subjects, default 20, at most 50.\"}}}}"},
	{"requirements", "requirements", "{\"name\":\"req_waive\",\"description\":\"Mark a verdict as a false positive (the model was wrong) or an accepted deviation (it is right and the exception is fine), with a reason. The verdict stays, marked. Take the verdict number from req_check or req_get.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"verdict_id\":{\"type\":\"number\",\"description\":\"The verdict number (#N).\"},\"kind\":{\"type\":\"string\",\"enum\":[\"false_positive\",\"accepted_deviation\"]},\"reason\":{\"type\":\"string\",\"description\":\"Required: why.\"}},\"required\":[\"verdict_id\",\"kind\",\"reason\"]}}"},
	{"itsas", "", "{\"name\":\"feedback\",\"description\":\"Alias of retro with kind=stam_issue: report a problem with stam or its MCP tools. Use retro, the one place to report, for new reports. Not for bugs in the project you are working on.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"kind\":{\"type\":\"string\",\"enum\":[\"bug\",\"inconsistency\",\"missing_param\",\"missing_feature\",\"other\"],\"description\":\"bug, inconsistency, missing_param, missing_feature, or other.\"},\"title\":{\"type\":\"string\",\"description\":\"Required. 1-4 words, a noun phrase that names the problem, like `send_mail reply_to`: no sentence, no colon. summary keeps the one line.\"},\"summary\":{\"type\":\"string\",\"description\":\"One line.\"},\"details\":{\"type\":\"string\",\"description\":\"What happened, what you expected, and the tool or route involved.\"},\"tool\":{\"type\":\"string\",\"description\":\"The MCP tool involved, if any.\"}},\"required\":[\"kind\",\"summary\",\"details\"]}}"},
	{"itsas", "", "{\"name\":\"retro\",\"description\":\"Record how the work went: a time sink, a misleading instruction, a trick that worked, or an idea. A retro item is about the work. A problem with stam or its MCP tools is kind=stam_issue with feedback_kind and tool: the one place to report those, filed under Feedback with one mail to the chief of staff. Search first with search: it finds open retro items and feedback reports by meaning, best first, up to three, each with its +1 count and the first line of its details, so a match worded differently is still visible. +1 a match with plus_one and your own scenario rather than filing a near-duplicate. Otherwise file it with kind, title, summary and details. One or two sentences.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"search\":{\"type\":\"string\",\"description\":\"Search open retro items and feedback reports by meaning, best first. Returns up to three matches with their +1 counts and the first line of their details.\"},\"plus_one\":{\"type\":\"string\",\"description\":\"The key of a retro item or feedback report to +1, like S-42. Needs details.\"},\"kind\":{\"type\":\"string\",\"enum\":[\"went_well\",\"improve\",\"idea\",\"instruction\",\"stam_issue\"],\"description\":\"went_well, improve, idea, instruction, or stam_issue.\"},\"feedback_kind\":{\"type\":\"string\",\"enum\":[\"bug\",\"inconsistency\",\"missing_param\",\"missing_feature\",\"other\"],\"description\":\"For stam_issue: bug, inconsistency, missing_param, missing_feature, or other.\"},\"tool\":{\"type\":\"string\",\"description\":\"For stam_issue: the MCP tool involved, if any.\"},\"title\":{\"type\":\"string\",\"description\":\"Required when filing a new item (not for search or plus_one). 1-4 words, a noun phrase that names the item, like `Idle pane waits`: no sentence, no colon. It becomes the ITSA title; summary keeps the one-line lesson.\"},\"summary\":{\"type\":\"string\",\"description\":\"One line: the lesson.\"},\"details\":{\"type\":\"string\",\"description\":\"The specific scenario: what happened, and where.\"},\"target\":{\"type\":\"string\",\"description\":\"The template, tool, or file it is about, such as type-developer or ring_submit. Required for improve and instruction.\"},\"evidence\":{\"type\":\"string\",\"enum\":[\"human\",\"gate\",\"review\",\"rollback\",\"measured\",\"none\"],\"description\":\"What external event backs the item: human (a correction from the human), gate (a merge gate result), review (a review verdict), rollback (a rollback or deploy hold), measured (a measured wait or cost), or none (default).\"},\"evidence_detail\":{\"type\":\"string\",\"description\":\"For evidence: the specifics, like \\\"phone 360-light failed on #183\\\".\"},\"when\":{\"type\":\"string\",\"description\":\"One line: the condition under which the lesson applies.\"},\"final\":{\"type\":\"boolean\",\"description\":\"true for your final round, when stam archives you: record your effort split with effort. Not an ITSA.\"},\"effort\":{\"type\":\"object\",\"description\":\"For final: percentages of your work over reading, implementing, testing, waiting, review_fixes, and coordination.\",\"properties\":{\"reading\":{\"type\":\"number\",\"minimum\":0,\"maximum\":100},\"implementing\":{\"type\":\"number\",\"minimum\":0,\"maximum\":100},\"testing\":{\"type\":\"number\",\"minimum\":0,\"maximum\":100},\"waiting\":{\"type\":\"number\",\"minimum\":0,\"maximum\":100},\"review_fixes\":{\"type\":\"number\",\"minimum\":0,\"maximum\":100},\"coordination\":{\"type\":\"number\",\"minimum\":0,\"maximum\":100}},\"additionalProperties\":false}}}}"},
	{"itsas", "", "{\"name\":\"itsa_get\",\"description\":\"One ITSA by id or key: title, status, owner, summary, parent chain, participants, links, and its direct children with each one's roll-up.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"ref\":{\"type\":\"string\",\"description\":\"ITSA id or key, like S-42.\"}},\"required\":[\"ref\"]}}"},
	{"itsas", "", "{\"name\":\"itsa_list\",\"description\":\"List ITSAs as short rows (key, status, owner, title). Filters: mine (you own or take part in), parent, subtree, status, category, owner, participant, kind, text. Use mine to see your own work.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"mine\":{\"type\":\"boolean\",\"description\":\"Only ITSAs you own or take part in.\"},\"parent\":{\"type\":\"string\",\"description\":\"Direct children of this ITSA; \\\"root\\\" for top-level ITSAs.\"},\"subtree\":{\"type\":\"string\",\"description\":\"This ITSA and everything below it.\"},\"status\":{\"type\":\"string\"},\"category\":{\"type\":\"string\",\"description\":\"backlog, ready, active, review, or closed.\"},\"owner\":{\"type\":\"string\"},\"participant\":{\"type\":\"string\"},\"kind\":{\"type\":\"string\"},\"text\":{\"type\":\"string\",\"description\":\"Match against title, summary, or body.\"}}}}"},
	{"itsas", "", "{\"name\":\"itsa_set\",\"description\":\"Change an ITSA: status, owner, title, summary, body, kind, parent, participants, or Work page column values (fields). Use a closed status to finish it. Use a human status only for a question only your user can answer (post a comment with itsa_post first: a human status is refused until you have); for anything your parent or the chief of staff can decide, use waiting or blocked. Moving an ITSA out of a human status withdraws the ask from your user. Returns what changed.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"ref\":{\"type\":\"string\",\"description\":\"ITSA id or key.\"},\"title\":{\"type\":\"string\",\"description\":\"1-4 words, a noun phrase that names the thing, like `Phone mail header`: no sentence, no colon, no parent key. The one-line detail goes in summary.\"},\"summary\":{\"type\":\"string\"},\"body\":{\"type\":\"string\"},\"kind\":{\"type\":\"string\"},\"status\":{\"type\":\"string\",\"description\":\"A status name. A closed one finishes the ITSA.\"},\"owner\":{\"type\":\"string\",\"description\":\"An agent id or name, or \\\"human\\\".\"},\"parent\":{\"type\":\"string\",\"description\":\"Move it under this ITSA, or \\\"root\\\" to free it.\"},\"participants\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Replace the participant list (the owner stays one).\"},\"fields\":{\"type\":\"object\",\"description\":\"Values for Work page columns, by field key (see itsa_fields list); null clears one. For example {\\\"stage\\\": \\\"dev\\\"}.\"},\"incident\":{\"type\":\"boolean\",\"description\":\"Mark the ITSA an incident (true) or clear the mark (false). Only the chief of staff or your user may set it; a developer spawn with urgent incident then goes ahead under it or its child ITSAs. Closing the ITSA clears the mark.\"}},\"required\":[\"ref\"]}}"},
	{"itsas", "", "{\"name\":\"itsa_fields\",\"description\":\"The Work page columns, called ITSA fields: a field is a shared column that agents fill per ITSA (with itsa_set fields), and its description says what goes in it. action: list (default), create, update, remove, or order. create needs key (a slug), label, and type (text, number, choice, link, date, check); a choice field needs options. update and remove take field (key or id). order takes order: field keys, first to last. Your user may always change fields; while a chief of staff is set, only that agent may, and others get a refusal naming it: mail them to ask. With none set, any agent may, sparingly.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"action\":{\"type\":\"string\",\"enum\":[\"list\",\"create\",\"update\",\"remove\",\"order\"]},\"field\":{\"type\":\"string\",\"description\":\"update and remove: the field key or id.\"},\"key\":{\"type\":\"string\",\"description\":\"A slug: lowercase letters, digits, - and _.\"},\"label\":{\"type\":\"string\"},\"type\":{\"type\":\"string\",\"enum\":[\"text\",\"number\",\"choice\",\"link\",\"date\",\"check\"]},\"options\":{\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"value\":{\"type\":\"string\"},\"label\":{\"type\":\"string\"},\"tone\":{\"type\":\"string\",\"enum\":[\"ok\",\"warn\",\"bad\",\"muted\",\"accent\"]}},\"required\":[\"value\"]},\"description\":\"A choice field's options.\"},\"description\":{\"type\":\"string\",\"description\":\"What goes in this column, for the agents that fill it.\"},\"hint\":{\"type\":\"string\"},\"width\":{\"type\":\"string\",\"enum\":[\"s\",\"m\",\"l\"]},\"align\":{\"type\":\"string\",\"enum\":[\"start\",\"end\"]},\"card\":{\"type\":\"string\",\"enum\":[\"chip\",\"meta\"]},\"kinds\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"The ITSA kinds this field applies to, such as [\\\"issue\\\"]: other ITSAs skip it, and a value on one is refused. Omit or [] for every kind. Narrowing keeps values and hides them.\"},\"order\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"order: field keys, first to last.\"}}}}"},
	{"itsas", "", "{\"name\":\"itsa_link\",\"description\":\"Link an ITSA to something outside it, or record on one of its links. To add a link, give ref and a url (and system, or external_id). To link a branch for the merge queue, give ref, system \\\"branch\\\", external_id (the branch name), and repo (a name in settings.itsa.repos). To record on a branch link, give ref and n (its number), with any of: review ({verdict: approve, request_changes, or comment; summary}), tests ({passed, failed, skipped, command}), screenshots ([{mail_id, name}] naming attachments on mail, such as ones in the ITSA's thread). Each field given replaces that part of the record.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"ref\":{\"type\":\"string\",\"description\":\"ITSA id or key.\"},\"url\":{\"type\":\"string\",\"description\":\"A link's url. Optional for a branch link.\"},\"system\":{\"type\":\"string\",\"description\":\"The link kind: github, url, or branch.\"},\"external_id\":{\"type\":\"string\",\"description\":\"An outside id, such as a PR number, or a branch name for a branch link.\"},\"repo\":{\"type\":\"string\",\"description\":\"A branch link's repo: a name in settings.itsa.repos.\"},\"n\":{\"type\":\"number\",\"description\":\"The link number to record on (a branch link).\"},\"review\":{\"type\":\"object\",\"description\":\"{ verdict: approve | request_changes | comment, summary }.\"},\"tests\":{\"type\":\"object\",\"description\":\"{ passed, failed, skipped, command }: counts of whole numbers.\"},\"screenshots\":{\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"mail_id\":{\"type\":\"string\"},\"name\":{\"type\":\"string\"}},\"required\":[\"mail_id\",\"name\"]},\"description\":\"Attachments on mail that show the change.\"}},\"required\":[\"ref\"]}}"},
	{"itsas", "", "{\"name\":\"itsa_post\",\"description\":\"Comment on an ITSA, or post a status update, in the ITSA's mail thread (the first post creates the thread). It goes to the ITSA's participants except you, plus anyone in `to`, and makes you a participant. Your user gets it only when `to` names \\\"human\\\", even as a participant: to answer them in an ITSA thread, include \\\"human\\\" in `to`. Comments and updates arrive with the next idle batch and don't interrupt a working agent, unless you name the recipient as @name in the body or you own the ITSA. An update (kind \\\"update\\\", the ITSA owner's periodic report) needs a health: on_track, at_risk, or off_track. Answering an ITSA mail with send_mail and reply_to does the same as a comment. Write other issues as their key (S-12) and agents as @name; the web UI links both.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"itsa\":{\"type\":\"string\",\"description\":\"The ITSA's id or key, for example S-42.\"},\"body\":{\"type\":\"string\",\"description\":\"Markdown; mail components work.\"},\"kind\":{\"type\":\"string\",\"enum\":[\"comment\",\"update\"],\"description\":\"Default comment.\"},\"health\":{\"type\":\"string\",\"enum\":[\"on_track\",\"at_risk\",\"off_track\"],\"description\":\"Required for an update.\"},\"to\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Extra recipients besides the participants.\"},\"override\":{\"type\":\"string\",\"description\":\"Only when `to` names \\\"human\\\": a mail check refuses a post your user doesn't need or that breaks the rules for mail to them. If you disagree, repost with the reason here; it goes out and your user sees the reason.\"}},\"required\":[\"itsa\",\"body\"]}}"},
	{"itsas", "", "{\"name\":\"pr_open\",\"description\":\"Open a branch's pull request on GitHub, from any machine (S-514). It runs on the ITSA home, where gh is: it fetches the branch from storage (or, on the home, from your own worktree), pushes it to origin, and opens the PR, or replaces the body of the open PR for that branch. The body is the docs/pull-requests.md body: its ITSA, Gates, and Deploy lines first. With itsa, the ITSA gets the PR and branch links, and a branch you own that is not yet linked is linked to it. Returns the PR number and url; then watch_pr it. Every later push to the branch needs pr_open again: a push to origin reaches storage only, not GitHub, so pr_open is what updates the PR. Run it with predict: true first (S-3287): a dry run that needs no title or body, pushes nothing to GitHub and opens nothing, and returns the tests the gate adds for the branch (each with its path and rule), which LIGHT ones it ran and passed, and the exact NAME: PASS lines the body must carry. A prediction that fails or times out is an error, never an empty list.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"branch\":{\"type\":\"string\",\"description\":\"The branch you pushed to storage.\"},\"predict\":{\"type\":\"boolean\",\"description\":\"Dry run (default false): return the NAME: PASS lines the body must carry. Needs no title or body; pushes nothing to GitHub and opens no PR.\"},\"title\":{\"type\":\"string\",\"description\":\"One line. Not needed with predict.\"},\"body\":{\"type\":\"string\",\"description\":\"The PR body, in the docs/pull-requests.md format. Exactly one of body and body_file.\"},\"body_file\":{\"type\":\"string\",\"description\":\"The path of a file holding the PR body, in your worktree or your scratch dir (read on your machine, at most 256 KiB). Exactly one of body and body_file.\"},\"itsa\":{\"type\":\"string\",\"description\":\"The ITSA the branch delivers (id or key), to link the PR and branch to.\"}},\"required\":[\"branch\"]}}"},
	{"itsas", "", "{\"name\":\"pr_merge\",\"description\":\"Merge an approved pull request, from any machine (S-2279). The ITSA home starts the merge script for it, detached from your shell (a build without the merge scripts refuses, and you merge with gh pr merge), and mails you the outcome when it ends: the merge sha, a refusal with its reason, or \\\"not merged\\\" with the script's last lines (call again to retry). Only the tree that owns the PR's ITSA (its body's ITSA: line) or its branch, or the chief of staff, may merge it. A call while a merge of the PR runs returns that run. With status, it starts nothing and returns the run's state and queue place. With cancel (S-2709), it takes the PR out of the merge queue without closing it: the ITSA home stops the PR's merge run and worker by recorded pid and drops its queue ticket, on the same tree rules; you and the run's requester get a \\\"merge cancelled\\\" mail. If a train holds the gate lock and carries the PR, the cancel claims the PR's ticket and the train drops the PR before its merge (the result says the cancel is pending in the train, and the run's mail reports it); if the train already claimed the merge the cancel is refused as \\\"already merging\\\" and the PR merges; a lock held by anything else refuses the cancel with nothing changed. A PR with no run is an error.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"pr\":{\"type\":[\"string\",\"number\"],\"description\":\"The PR number.\"},\"status\":{\"type\":\"boolean\",\"description\":\"Only report the run's state, queue place, and last log lines. Default false.\"},\"cancel\":{\"type\":\"boolean\",\"description\":\"Take the PR out of the merge queue: stop its merge run and drop its ticket, without closing the PR. Default false.\"}},\"required\":[\"pr\"]}}"},
	{"itsas", "", "{\"name\":\"pr_close\",\"description\":\"Close a pull request with a comment, from any machine (S-2279), such as one a later PR superseded. It runs on the ITSA home, where gh is, on pr_merge's terms: only the tree that owns the PR's ITSA or its branch, or the chief of staff, may close it. A PR that is already closed or merged is left as it is.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"pr\":{\"type\":[\"string\",\"number\"],\"description\":\"The PR number.\"},\"comment\":{\"type\":\"string\",\"description\":\"Why it is closed, such as \\\"Superseded by #728.\\\"\"}},\"required\":[\"pr\",\"comment\"]}}"},
	{"itsas", "", "{\"name\":\"process_propose\",\"description\":\"Propose a change to a process (S-1085): the whole new processes/ID.yaml. The YAML is checked as a process file; a branch, a pull request and a proposal ITSA in needs_approval are made (as you). Nothing changes until your user approves the proposal and the PR merges; you cannot approve it yourself. base is required: the exact text of the file you started from (empty for a new process); the proposal is refused (409) if the process on main has changed since. Returns the ITSA key and the PR url.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"id\":{\"type\":\"string\",\"description\":\"The process id (the file name without .yaml).\"},\"yaml\":{\"type\":\"string\",\"description\":\"The full new file text.\"},\"summary\":{\"type\":\"string\",\"description\":\"What the change does and why.\"},\"base\":{\"type\":\"string\",\"description\":\"The exact file text you edited from (empty string for a new process). Refused with 409 when main has a different copy.\"}},\"required\":[\"id\",\"yaml\",\"summary\",\"base\"]}}"},
	{"itsas", "", "{\"name\":\"pr_view\",\"description\":\"Read a pull request, from any machine (S-3107): its title, state, base and head branches, the full head sha, its merge base with the base branch and the one git diff for the PR (S-3751), its body, the files changed with their +/- counts, and its checks and commit statuses (stam/review included). It runs on the ITSA home, where gh is, so you need no GitHub login. Read-only apart from refreshing storage's PR head mirror when it lags. pr is a number (in the home's default repo) or OWNER/REPO#N in a repo of settings.itsa.repos.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"pr\":{\"type\":[\"string\",\"number\"],\"description\":\"The PR number, or OWNER/REPO#N.\"}},\"required\":[\"pr\"]}}"},
	{"itsas", "", "{\"name\":\"pr_review\",\"description\":\"Give your verdict on a PR (S-1061), from any machine: a comment, \\\"Review (YOU): approve|request_changes. SUMMARY\\\", and the stam/review status on the PR's head, which merge-pr.mjs reads. It runs on the ITSA home, where gh is, as you: the reviewer is your own agent, never a name you pass. head is the full sha of the commit you reviewed; the verdict is refused (409) when the PR's head has moved since, so review the new head again.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"pr\":{\"type\":\"number\",\"description\":\"The PR number.\"},\"verdict\":{\"type\":\"string\",\"enum\":[\"approve\",\"request_changes\"],\"description\":\"Your verdict.\"},\"summary\":{\"type\":\"string\",\"description\":\"One line: why.\"},\"head\":{\"type\":\"string\",\"description\":\"The sha of the commit you reviewed: the full 40 characters, or a unique prefix of at least 7. The status is posted on the PR's full head.\"}},\"required\":[\"pr\",\"verdict\",\"summary\",\"head\"]}}"},
	{"events", "", "{\"name\":\"subscribe\",\"description\":\"Ask to be told about external events (GitHub, Linear, Slack, and other sources): each matching event arrives as a notice while you work, or as mail from stam when you are idle. Filter by source, subjects (glob patterns over keys like `github:OWNER/REPO#12`, `github:OWNER/*`, `linear:TEAM-123`, `slack:CHANNEL`), types (glob patterns like `pull_request.*`), actors, and exclude_actors. By default you subscribe yourself; pass `itsa` to notify an ITSA's thread instead, or `for` another agent in your tree (an ITSA you take part in, or the human, if allowed). Events close in time arrive as one message. Returns a subscription id for unsubscribe.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"source\":{\"type\":\"string\",\"description\":\"Only this source, for example github.\"},\"subjects\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Subject glob patterns; * matches within one segment.\"},\"types\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Event type glob patterns, for example pull_request.*.\"},\"actors\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Only events by these actors.\"},\"exclude_actors\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Skip events by these actors.\"},\"itsa\":{\"type\":\"string\",\"description\":\"Subscribe an ITSA (id or key): matching events post into its thread instead.\"},\"for\":{\"type\":\"string\",\"description\":\"Subscribe another agent (id or name) in your tree, or \\\"human\\\". Defaults to you.\"},\"note\":{\"type\":\"string\",\"description\":\"A short label carried in the deliveries.\"},\"expires_in_minutes\":{\"type\":\"number\",\"description\":\"Let the subscription expire after this many minutes.\"}}}}"},
	{"events", "", "{\"name\":\"unsubscribe\",\"description\":\"Remove one of your event subscriptions (or one you created) by its id, from subscribe or list_subscriptions.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"id\":{\"type\":\"string\",\"description\":\"The subscription id.\"}},\"required\":[\"id\"]}}"},
	{"events", "", "{\"name\":\"list_subscriptions\",\"description\":\"List event subscriptions you made or that name you as the subscriber: id, subscriber, filter, note, and expiry.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"}}}}"},
	{"events", "", "{\"name\":\"watch_pr\",\"description\":\"Watch a pull request: its checks, reviews, comments, pushes, and merge or close reach you as they happen, as notices while you work or as mail when you are idle. pr is a number (in the default repo of the ITSA home: settings.itsa.prOpen.github there, else its origin), OWNER/REPO#N, or a PR url. events narrows what you hear: checks, reviews, comments, pushes, merged, closed (default all). A merge or close always ends the watch, and is always delivered. To wait for CI, use wait_for on event with subject github:OWNER/REPO#N and type checks.completed. Watching again replaces the earlier watch. Pass for to watch on another agent's behalf.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"pr\":{\"type\":[\"string\",\"number\"],\"description\":\"The PR number, OWNER/REPO#N, or its url.\"},\"events\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"enum\":[\"checks\",\"reviews\",\"comments\",\"pushes\",\"merged\",\"closed\"]},\"description\":\"What to hear: checks, reviews, comments, pushes, merged, closed. Default all.\"},\"for\":{\"type\":\"string\",\"description\":\"Watch for another agent (id) in your tree, or \\\"human\\\". Defaults to you.\"}},\"required\":[\"pr\"]}}"},
	{"events", "", "{\"name\":\"unwatch_pr\",\"description\":\"Stop watching a pull request you watch with watch_pr. pr is as watch_pr takes it.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"pr\":{\"type\":[\"string\",\"number\"],\"description\":\"The PR number, OWNER/REPO#N, or its url.\"},\"for\":{\"type\":\"string\",\"description\":\"The agent (id) or \\\"human\\\" you watched for, if not you.\"}},\"required\":[\"pr\"]}}"},
	{"layout", "", "{\"name\":\"layout_get\",\"description\":\"Read the human's web layout: each world's panes as an indented tree (tabs, which tab is active, which pane is focused), then the raw layout JSON with its version. Read it before you arrange anything. Use layout_arrange only when the human asked you to arrange their screen.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"}}}}"},
	{"layout", "", "{\"name\":\"layout_arrange\",\"description\":\"Arrange the human's web layout (panes and tabs) with a batch of ops, applied all or none. Act only when the human asked you to arrange their screen (for example \\\"open my usage page beside this agent\\\"); never rearrange it on your own initiative. Read the layout first with layout_get, and pass its version as base so a change made meanwhile is refused (409) rather than overwritten. Tab keys name views: agent:ID (an agent's terminal), view:ID (stam's own conversation view of an agent), details:ID, instructions:ID, mail:ID (mail:human is the human's inbox), thread:ID (a mail thread), itsa:ID (an ITSA), board:ID or board:all (ITSA boards), shell:MACHINE:ID, config (Settings), usage. World: \\\"main\\\" is the layout's current world (or home when none is current): the world an agent last sent the human to, not necessarily what each device shows, since the human's own navigation stays on that device. A current op moves every device to its world; other worlds are named as the layout names them (agent IDs, t:THREAD, w:config, w:usage, w:itsa:ID). Returns the new layout as layout_get does. An invalid op or a stale base returns the error and changes nothing.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"base\":{\"type\":\"integer\",\"description\":\"The layout version you read with layout_get. A different current version is refused.\"},\"ops\":{\"type\":\"array\",\"description\":\"Applied in order.\",\"items\":{\"oneOf\":[{\"type\":\"object\",\"description\":\"open: show a tab in a world; splits beside pane, or adds to it. Opens in the background when background is true.\",\"required\":[\"op\",\"world\",\"key\"],\"properties\":{\"op\":{\"const\":\"open\"},\"world\":{\"type\":\"string\"},\"key\":{\"type\":\"string\",\"description\":\"A tab key such as agent:ID.\"},\"pane\":{\"type\":\"string\",\"description\":\"Pane to put it in (default: the focused pane).\"},\"split\":{\"enum\":[\"right\",\"left\",\"down\",\"up\"],\"description\":\"Make a new pane beside the pane, on this side.\"},\"background\":{\"type\":\"boolean\"}},\"additionalProperties\":false},{\"type\":\"object\",\"description\":\"close: remove a tab from its pane; an empty pane goes.\",\"required\":[\"op\",\"world\",\"key\"],\"properties\":{\"op\":{\"const\":\"close\"},\"world\":{\"type\":\"string\"},\"key\":{\"type\":\"string\"}},\"additionalProperties\":false},{\"type\":\"object\",\"description\":\"swap: show a tab in place of another, in the same pane and place (an agent's terminal agent:ID and stam's view of it view:ID trade places); with, open elsewhere in the world, moves there.\",\"required\":[\"op\",\"world\",\"key\",\"with\"],\"properties\":{\"op\":{\"const\":\"swap\"},\"world\":{\"type\":\"string\"},\"key\":{\"type\":\"string\"},\"with\":{\"type\":\"string\"}},\"additionalProperties\":false},{\"type\":\"object\",\"description\":\"move: move a tab to a pane, before a tab, or to a new pane on a side.\",\"required\":[\"op\",\"world\",\"key\",\"to\"],\"properties\":{\"op\":{\"const\":\"move\"},\"world\":{\"type\":\"string\"},\"key\":{\"type\":\"string\"},\"to\":{\"type\":\"string\",\"description\":\"Target pane id.\"},\"before\":{\"type\":[\"string\",\"null\"],\"description\":\"Tab key to put it before.\"},\"side\":{\"enum\":[\"right\",\"left\",\"down\",\"up\"]}},\"additionalProperties\":false},{\"type\":\"object\",\"description\":\"split: make an empty pane beside a pane (or move its active tab into the new pane when it has several).\",\"required\":[\"op\",\"world\",\"pane\",\"side\"],\"properties\":{\"op\":{\"const\":\"split\"},\"world\":{\"type\":\"string\"},\"pane\":{\"type\":\"string\"},\"side\":{\"enum\":[\"right\",\"left\",\"down\",\"up\"]}},\"additionalProperties\":false},{\"type\":\"object\",\"description\":\"closePane: close a pane; its tabs join a neighbour.\",\"required\":[\"op\",\"world\",\"pane\"],\"properties\":{\"op\":{\"const\":\"closePane\"},\"world\":{\"type\":\"string\"},\"pane\":{\"type\":\"string\"}},\"additionalProperties\":false},{\"type\":\"object\",\"description\":\"activate: make a tab the active one in its pane.\",\"required\":[\"op\",\"world\",\"pane\",\"key\"],\"properties\":{\"op\":{\"const\":\"activate\"},\"world\":{\"type\":\"string\"},\"pane\":{\"type\":\"string\"},\"key\":{\"type\":\"string\"}},\"additionalProperties\":false},{\"type\":\"object\",\"description\":\"focus: make a pane the focused one.\",\"required\":[\"op\",\"world\",\"pane\"],\"properties\":{\"op\":{\"const\":\"focus\"},\"world\":{\"type\":\"string\"},\"pane\":{\"type\":\"string\"}},\"additionalProperties\":false},{\"type\":\"object\",\"description\":\"tabBar: show or hide a pane's tab bar.\",\"required\":[\"op\",\"world\",\"pane\",\"on\"],\"properties\":{\"op\":{\"const\":\"tabBar\"},\"world\":{\"type\":\"string\"},\"pane\":{\"type\":\"string\"},\"on\":{\"type\":\"boolean\"}},\"additionalProperties\":false},{\"type\":\"object\",\"description\":\"setRoot: replace a world's whole pane tree. root is a pane or a split node (id, split row|col, children, sizes; a pane has id, tabs, active).\",\"required\":[\"op\",\"world\",\"root\"],\"properties\":{\"op\":{\"const\":\"setRoot\"},\"world\":{\"type\":\"string\"},\"root\":{\"type\":\"object\"},\"focusKey\":{\"type\":\"string\",\"description\":\"Focus the pane holding this tab.\"}},\"additionalProperties\":false},{\"type\":\"object\",\"description\":\"current: send the human to a world: every device switches to it, and it becomes the one \\\"main\\\" names; null for home.\",\"required\":[\"op\",\"world\"],\"properties\":{\"op\":{\"const\":\"current\"},\"world\":{\"type\":[\"string\",\"null\"]}},\"additionalProperties\":false}]}}},\"required\":[\"ops\"]}}"},
}
